/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Functions: setupVideoGrid, changeVideoGrid
 *   Constants: gridPath, headers, firstId, secondId, first, second, screenshots
 * Tests
 *   - one configurable Video Grid saves complete order and default display for the listener
 *   - an uncertain Video Grid save retries its frozen operation without reapplying a different order
 *   - a refused stale Video Grid save requires a refreshed draft and a new approval
 *   - a stale Video continuation keeps visible cards until an explicit restart uses the new order
 *   - Chinese Video Grid controls and complete-order confirmation reflow on desktop and narrow screens
 * @end-catalog */

import { mkdir } from 'node:fs/promises';
import type { Page } from '@playwright/test';
import { capabilities, session, viewer } from '../src/features/admin/adminFixtures.testSupport';
import { trackFixtures } from './fixtures/catalog';
import { expectNoUnownedAxeViolations } from './support/accessibility';
import { installPrivateListenerRoutes } from './support/privateRoutes';
import { expect, test } from './support/test';

const gridPath = '/api/admin/v1/pages/videos/grid';
const headers = { 'X-Finitude-Account-Viewer': viewer, 'Cache-Control': 'no-store' };
const firstId = '111111111111111111111111', secondId = '222222222222222222222222';
const first = { ...trackFixtures[0], id: firstId, title: 'Evening light', mediaType: 'video' as const };
const second = { ...trackFixtures[0], id: secondId, title: 'A quiet morning', mediaType: 'video' as const };
const screenshots = '/tmp/finitude-admin-video-grid';

/** One synthetic server state connects administrator configuration to the public Video route. */
async function setupVideoGrid(page: Page, locale: 'en-US' | 'zh-Hans' = 'en-US') {
  const writes: Array<Record<string, unknown>> = [];
  let sequence = 0, defaultView: 'grid' | 'immersive' = 'grid';
  let tracks = [first, second];
  let failure: 'none' | 'unknown' | 'conflict' = 'none';
  const receipts = new Map<string, { body: Record<string, unknown>; response: unknown }>();
  const revision = () => `cr_${String.fromCharCode(97 + sequence).repeat(43)}`;
  const grid = () => ({ revision: revision(), defaultView, items: tracks.map(track => ({
    id: track.id, title: track.title, coverUrl: null, creator: 'Finitude Ensemble'
  })) });
  await page.addInitScript(value => window.localStorage.setItem('finitude.localization.preference.v1', value), locale);
  await page.emulateMedia({ reducedMotion: 'reduce' });
  await installPrivateListenerRoutes(page, { session, playlists: [] });
  await page.route('**/api/listener/v1/capabilities', route => route.fulfill({ json: { playlists: false } }));
  await page.route('**/api/listener/v1/videos?**', route => route.fulfill({ json: { items: tracks, nextCursor: null, defaultView } }));
  await page.route('**/api/admin/v1/**', async route => {
    const request = route.request(), path = new URL(request.url()).pathname;
    expect(request.headers()['x-finitude-account-viewer']).toBe(viewer);
    if (path === '/api/admin/v1/capabilities') return route.fulfill({ json: { ...capabilities, catalog: { editing: true, visibility: true } }, headers });
    if (path === gridPath && request.method() === 'GET') return route.fulfill({ json: { grid: grid() }, headers });
    if (path === gridPath && request.method() === 'PATCH') {
      const body = request.postDataJSON() as Record<string, unknown>;
      writes.push(body);
      const operationId = String(body.operationId), recorded = receipts.get(operationId);
      if (recorded) {
        expect(body).toEqual(recorded.body);
        return route.fulfill({ json: recorded.response, headers });
      }
      if (failure === 'conflict') {
        sequence++;
        return route.fulfill({ status: 409, json: { code: 'ADMIN_PAGE_CONFLICT' }, headers });
      }
      expect(Object.keys(body).sort()).toEqual(['defaultView', 'expectedRevision', 'operationId', 'videoIds']);
      expect(body.expectedRevision).toBe(revision());
      expect((body.videoIds as string[]).slice().sort()).toEqual(tracks.map(track => track.id).sort());
      const byId = new Map(tracks.map(track => [track.id, track]));
      tracks = (body.videoIds as string[]).map(id => byId.get(id)!);
      defaultView = body.defaultView as typeof defaultView; sequence++;
      const response = { grid: grid(), receipt: { operationId } };
      receipts.set(operationId, { body: structuredClone(body), response });
      if (failure === 'unknown') {
        failure = 'none';
        return route.fulfill({ status: 503, json: { code: 'SYNTHETIC_LOST_RECEIPT' }, headers });
      }
      return route.fulfill({ json: response, headers });
    }
    if (request.method() === 'GET' && /^\/api\/admin\/v1\/pages\/(home|library|search|videos)$/.test(path)) {
      const slug = path.split('/').at(-1)!;
      const items = slug === 'videos' ? [{ itemId: '333333333333333333333333', itemType: 'grid',
        referenceId: '444444444444444444444444', order: 0, visibility: 'public', name: 'Video', sourceMode: 'dynamic', referenceStatus: 'ready' }] : [];
      return route.fulfill({ json: { page: { slug, title: slug === 'videos' ? 'Video' : slug, revision: revision(), items } }, headers });
    }
    throw new Error(`Unexpected Video Grid request: ${request.method()} ${path}`);
  });
  await page.goto('/finitude/admin/pages');
  await page.getByRole('button', { name: locale === 'zh-Hans' ? '切换到管理员视角' : 'Switch to Admin view', exact: true }).click();
  await expect(page.getByRole('button', { name: locale === 'zh-Hans' ? '视频' : 'Video', exact: true })).toBeVisible();
  return { writes, fail: (value: typeof failure) => { failure = value; },
    append: () => { tracks = [...tracks, { ...first, id: '555555555555555555555555', title: 'Newly published Video' }]; sequence++; } };
}

/** Uses the keyboard path so ordering remains possible without pointer dragging. */
async function changeVideoGrid(page: Page) {
  await page.getByRole('button', { name: 'Video', exact: true }).click();
  await page.getByRole('button', { name: 'Configure video Grid', exact: true }).click();
  const draft = page.getByRole('list', { name: 'Draft order', exact: true });
  const handle = draft.getByRole('button', { name: 'Reorder Evening light', exact: true });
  await handle.focus(); await handle.press('ArrowDown');
  await expect(draft.getByRole('listitem').first()).toContainText(second.title);
  await expect(handle).toBeFocused();
  await page.getByRole('combobox', { name: 'Default display', exact: true }).selectOption('immersive');
}

test('one configurable Video Grid saves complete order and default display for the listener', async ({ page }) => {
  await page.setViewportSize({ width: 1440, height: 1100 });
  const server = await setupVideoGrid(page);
  await page.getByRole('button', { name: 'Search', exact: true }).click();
  await expect(page.getByText('Search is a functional page. Its results follow each listener’s query and have no configured page items.', { exact: true })).toBeVisible();
  await expect(page.getByRole('button', { name: 'Adjust order', exact: true })).toHaveCount(0);
  await expect(page.getByRole('button', { name: 'Hide this placement', exact: true })).toHaveCount(0);
  await changeVideoGrid(page);
  expect(server.writes).toHaveLength(0);
  await page.getByRole('button', { name: 'Cancel adjustment', exact: true }).click();
  expect(server.writes).toHaveLength(0);
  await expect(page.getByRole('heading', { name: '1 · Video', exact: true })).toBeVisible();
  await expect(page.getByRole('main').getByRole('listitem')).toHaveCount(1);
  await changeVideoGrid(page);
  await mkdir(screenshots, { recursive: true });
  await page.screenshot({ path: `${screenshots}/draft-desktop.png`, fullPage: true, animations: 'disabled' });
  await page.setViewportSize({ width: 320, height: 900 });
  await page.getByRole('heading', { name: 'Configure video Grid', exact: true }).evaluate(node => node.scrollIntoView({ block: 'start' }));
  expect(await page.evaluate(() => document.documentElement.scrollWidth <= innerWidth && document.body.scrollWidth <= innerWidth)).toBe(true);
  await page.screenshot({ path: `${screenshots}/draft-320.png`, fullPage: true, animations: 'disabled' });
  await expectNoUnownedAxeViolations(page, 'admin-video-grid-draft-320');
  await page.getByRole('button', { name: 'Save order', exact: true }).click();
  const confirmation = page.getByRole('dialog', { name: 'Save video Grid?', exact: true });
  await expect(confirmation).toContainText(second.title);
  await expect(confirmation).toContainText(first.title);
  await expect(confirmation).toContainText('Immersive preview');
  expect(server.writes).toHaveLength(0);
  await confirmation.getByRole('button', { name: 'Confirm save order', exact: true }).click();
  await expect.poll(() => server.writes.length).toBe(1);
  expect(server.writes[0]).toMatchObject({ videoIds: [secondId, firstId], defaultView: 'immersive' });
  await expect(confirmation).toHaveCount(0);
  await page.reload();
  await page.getByRole('button', { name: 'Video', exact: true }).click();
  await page.getByRole('button', { name: 'Configure video Grid', exact: true }).click();
  await expect(page.getByRole('combobox', { name: 'Default display', exact: true })).toHaveValue('immersive');
  await expect(page.getByRole('list', { name: 'Draft order', exact: true }).getByRole('listitem').first()).toContainText(second.title);
  await page.getByRole('button', { name: 'Cancel adjustment', exact: true }).click();
  await page.getByRole('button', { name: 'Current view: Admin', exact: true }).click();
  await page.getByRole('menuitemradio', { name: 'User', exact: true }).click();
  await page.getByRole('link', { name: 'Video', exact: true }).click();
  await expect(page.getByRole('button', { name: 'Immersive preview', exact: true })).toHaveAttribute('aria-pressed', 'true');
  const previews = page.getByRole('list', { name: 'Video previews', exact: true });
  await expect(previews.getByRole('heading')).toHaveText([second.title, first.title]);
  server.append(); await page.reload();
  await expect(previews.getByRole('heading')).toHaveText([second.title, first.title, 'Newly published Video']);
  await page.getByRole('button', { name: 'Grid', exact: true }).click();
  await page.reload();
  await expect(page.getByRole('button', { name: 'Grid', exact: true })).toHaveAttribute('aria-pressed', 'true');
  expect(await page.evaluate(() => document.documentElement.scrollWidth <= innerWidth)).toBe(true);
  await page.screenshot({ path: `${screenshots}/listener-320.png`, fullPage: true, animations: 'disabled' });
  await expectNoUnownedAxeViolations(page, 'configured-video-grid-listener-320');
});

test('an uncertain Video Grid save retries its frozen operation without reapplying a different order', async ({ page }) => {
  const server = await setupVideoGrid(page);
  await changeVideoGrid(page); server.fail('unknown');
  await page.getByRole('button', { name: 'Save order', exact: true }).click();
  await page.getByRole('dialog').getByRole('button', { name: 'Confirm save order', exact: true }).click();
  await expect(page.getByRole('button', { name: 'Retry original operation', exact: true })).toBeVisible();
  await page.getByRole('button', { name: 'Search', exact: true }).click();
  await page.getByRole('button', { name: 'Video', exact: true }).click();
  await expect(page.getByRole('button', { name: 'Configure video Grid', exact: true })).toBeDisabled();
  await expect(page.getByRole('alert')).toContainText('Immersive preview');
  await page.getByRole('button', { name: 'Retry original operation', exact: true }).click();
  await expect.poll(() => server.writes.length).toBe(2);
  expect(server.writes[1]).toEqual(server.writes[0]);
  await expect(page.getByRole('button', { name: 'Retry original operation', exact: true })).toHaveCount(0);
});

test('a refused stale Video Grid save requires a refreshed draft and a new approval', async ({ page }) => {
  const server = await setupVideoGrid(page);
  await changeVideoGrid(page); server.fail('conflict');
  await page.getByRole('button', { name: 'Save order', exact: true }).click();
  await page.getByRole('dialog').getByRole('button', { name: 'Confirm save order', exact: true }).click();
  await expect(page.getByRole('dialog', { name: 'Save video Grid?', exact: true })).toHaveCount(0);
  const warning = page.getByRole('alert');
  await expect(warning).toContainText('The Video Grid changed.');
  await expect(page.getByRole('button', { name: 'Retry original operation', exact: true })).toHaveCount(0);
  await expect(page.getByRole('button', { name: 'Save order', exact: true })).toBeDisabled();
  server.fail('none');
  await warning.getByRole('button', { name: 'Refresh and adjust again', exact: true }).click();
  const draft = page.getByRole('list', { name: 'Draft order', exact: true });
  await expect(draft.getByRole('listitem').first()).toContainText(first.title);
  await expect(page.getByRole('combobox', { name: 'Default display', exact: true })).toHaveValue('grid');
  await expect(page.getByRole('button', { name: 'Save order', exact: true })).toBeDisabled();
  expect(server.writes).toHaveLength(1);
  await draft.getByRole('button', { name: 'Move down Evening light', exact: true }).click();
  await page.getByRole('button', { name: 'Save order', exact: true }).click();
  expect(server.writes).toHaveLength(1);
  await page.getByRole('dialog').getByRole('button', { name: 'Confirm save order', exact: true }).click();
  await expect.poll(() => server.writes.length).toBe(2);
  expect(server.writes[1].operationId).not.toBe(server.writes[0].operationId);
  expect(server.writes[1].expectedRevision).not.toBe(server.writes[0].expectedRevision);
});

test('a stale Video continuation keeps visible cards until an explicit restart uses the new order', async ({ page }) => {
  const cursor = 'synthetic-video-snapshot-cursor';
  const reads: Array<string | null> = [];
  let changed = false;
  await page.route('**/api/listener/v1/videos?**', route => {
    const after = new URL(route.request().url()).searchParams.get('cursor');
    reads.push(after);
    if (after) {
      changed = true;
      return route.fulfill({ status: 409, json: { code: 'stale_video_cursor' } });
    }
    return route.fulfill({ json: { defaultView: 'grid',
      items: changed ? [second, first] : [first], nextCursor: changed ? null : cursor } });
  });
  await page.goto('/finitude/videos');
  const main = page.getByRole('main');
  await expect(main.getByRole('listitem')).toContainText([first.title]);
  await main.getByRole('button', { name: 'Load more', exact: true }).click();
  await expect(main.getByRole('alert')).toBeVisible();
  await expect(main.getByRole('listitem')).toContainText([first.title]);
  await main.getByRole('button', { name: 'Try again', exact: true }).click();
  await expect(main.getByRole('listitem')).toContainText([second.title, first.title]);
  await expect(main.getByRole('button', { name: 'Load more', exact: true })).toHaveCount(0);
  expect(reads).toEqual([null, cursor, null]);
});

test('Chinese Video Grid controls and complete-order confirmation reflow on desktop and narrow screens', async ({ page }) => {
  const server = await setupVideoGrid(page, 'zh-Hans');
  await page.getByRole('button', { name: '视频', exact: true }).click();
  await page.getByRole('button', { name: '配置视频网格', exact: true }).click();
  await page.getByRole('combobox', { name: '默认展示方式', exact: true }).selectOption('immersive');
  await page.getByRole('button', { name: '调整 Evening light 的顺序', exact: true }).press('ArrowDown');
  await mkdir(screenshots, { recursive: true });
  for (const width of [1440, 320]) {
    await page.setViewportSize({ width, height: 1000 });
    if (width === 320) await page.getByRole('heading', { name: '配置视频网格', exact: true }).evaluate(node => node.scrollIntoView({ block: 'start' }));
    expect(await page.evaluate(() => document.documentElement.scrollWidth <= innerWidth && document.body.scrollWidth <= innerWidth)).toBe(true);
    await page.screenshot({ path: `${screenshots}/draft-zh-${width}.png`, fullPage: true, animations: 'disabled' });
  }
  await expectNoUnownedAxeViolations(page, 'admin-video-grid-zh-320');
  await page.getByRole('button', { name: '保存顺序', exact: true }).click();
  const confirmation = page.getByRole('dialog', { name: '保存视频网格？', exact: true });
  await expect(confirmation).toContainText('沉浸预览');
  await expect(confirmation).toContainText(first.title);
  await expect(confirmation).toContainText(second.title);
  expect(await page.evaluate(() => document.documentElement.scrollWidth <= innerWidth)).toBe(true);
  await page.screenshot({ path: `${screenshots}/confirmation-zh-320.png`, fullPage: true, animations: 'disabled' });
  await page.keyboard.press('Escape');
  await page.getByRole('button', { name: '取消调整', exact: true }).click();
  expect(server.writes).toHaveLength(0);
});
